python3 - <<'PY'
stripe = {'Feldman': 30000, 'Freeman': 12000, 'Greenwald': 30000, 'Weiss': 40000, 'Abernathy': 50000, 'Castellano': 30000, 'Ellsworth': 10000, 'Harrington': 35000, 'Lindqvist': 25000, 'Nakashima': 20000, 'Okonkwo': 45000, 'Pemberton': 25000, 'Vanderberg': 20000, 'Whitfield': 30000}
paypal = {'Freeman': 8000, 'Greenwald': 12000, 'Weiss': 20000, 'Roth': 15000, 'Abernathy': 20000, 'Dunmore': 25000, 'Harrington': 15000, 'Lindqvist': 15000, 'Nakashima': 15000, 'Okonkwo': 20000, 'Pemberton': 15000, 'Whitfield': 15000}
square = {'Greenwald': 8000, 'Abernathy': 10000, 'Castellano': 15000, 'Harrington': 10000, 'Marchetti': 20000}
direct = {'Sinclair': 20000, 'Vanderberg': 10000}
books = {"Feldman": 30000, "Freeman": 20000, "Greenwald": 50000, "Weiss": 60000, "Roth": 15000, "Abernathy": 80000, "Castellano": 45000, "Dunmore": 25000, "Ellsworth": 10000, "Harrington": 60000, "Lindqvist": 40000, "Marchetti": 20000, "Nakashima": 35000, "Okonkwo": 65000, "Pemberton": 40000, "Rosenthal": 0, "Sinclair": 20000, "Vanderberg": 30000, "Whitfield": 45000}
total = 0
for k in books:
    s = stripe.get(k, 0) + paypal.get(k, 0) + square.get(k, 0) + direct.get(k, 0)
    total += s
    print(k, s, "ok" if s == books[k] else "MISMATCH")
print("channels_total", total, "books", sum(books.values()), "match")
PY

